function F({registerIndicator:b,nulls:p}){b({id:"oa-rwma",name:"RWMA: Range Weighted Moving Average",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:14,min:1,max:2e3,step:1}],plots:[{key:"rwma",type:"line",title:"RWMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(n,w){const m=Math.max(1,Math.floor(Number(w.period)||14)),h=n.length,s=new Array(h).fill(NaN);let l=0,o=0,a=0,c=0;for(let t=0;t<h;t++){const i=n[t],N=Number.isFinite(i.high)&&Number.isFinite(i.low),r=Number.isFinite(i.close);if(N){const e=Math.max(i.high-i.low,0);o+=e,r&&(l+=i.close*e)}else a++;r||c++;const u=t-m;if(u>=0){const e=n[u],y=Number.isFinite(e.high)&&Number.isFinite(e.low),f=Number.isFinite(e.close);if(y){const g=Math.max(e.high-e.low,0);o-=g,f&&(l-=e.close*g)}else a--;f||c--}const d=r?i.close:NaN;if(a>0||t<m-1){s[t]=d;continue}c>0||(s[t]=o>0?l/o:d)}return{rwma:p(s)}}})}export{F as default};
